package com.turboio.addon;
import java.io.*;import java.nio.channels.*;import java.nio.file.*;import java.util.*;

/** Bounded metadata only. An unfinished start marker survives a process death;
 * unknown in-memory tails stay distinct from known rejected/unconfirmed batches. */
final class LifelogAudioHealth implements LifelogAudioCollector.Health {
 private final File directory,file;private final AtomicDocument document;private final String account;private volatile Map<String,Object> value;private boolean started,finished;
 LifelogAudioHealth(File files,String account)throws IOException{
  require(account!=null&&account.matches("[a-f0-9]{64}"),"AUDIO_HEALTH_ACCOUNT");this.account=account;directory=new File(files.getCanonicalFile(),"lifelog-audio-health");if(!directory.exists()){require(directory.mkdir(),"AUDIO_HEALTH_DIRECTORY");sync(directory.getParentFile());}check(directory,true);
  File[] children=directory.listFiles();require(children!=null&&children.length<=96,"AUDIO_HEALTH_BUDGET");Set<String> accounts=new HashSet<>();for(File f:children){require(f.getName().matches("[a-f0-9]{64}\\.json(?:\\.partial|\\.lock)?"),"AUDIO_HEALTH_PATH");check(f,false);require(f.length()<=65536,"AUDIO_HEALTH_BUDGET");accounts.add(f.getName().substring(0,64));}require(accounts.contains(account)||accounts.size()<32,"AUDIO_HEALTH_BUDGET");file=new File(directory,account+".json");paths();AtomicDocument opened=null;
  try{opened=new AtomicDocument(file,65536);document=opened;Object prior=document.read();if(prior==null)value=WireJson.object("schema",1,"account",account,"interrupted_runs",0L,"rejected_batches",0L,"unconfirmed_batches",0L,"last_error","","active",null);else{value=WireJson.map(prior);require(value.keySet().equals(new HashSet<>(Arrays.asList("schema","account","interrupted_runs","rejected_batches","unconfirmed_batches","last_error","active")))&&Long.valueOf(1).equals(value.get("schema"))&&account.equals(value.get("account")),"AUDIO_HEALTH_STATE");for(String k:new String[]{"interrupted_runs","rejected_batches","unconfirmed_batches"})number(value,k);require(value.get("last_error") instanceof String&&((String)value.get("last_error")).matches("[A-Z_]{0,90}"),"AUDIO_HEALTH_STATE");if(value.get("active")!=null){Map<String,Object> active=WireJson.map(value.get("active"));require(active.get("finalized") instanceof Boolean&&active.keySet().equals(Boolean.TRUE.equals(active.get("finalized"))?new HashSet<>(Arrays.asList("context","finalized","status")):new HashSet<>(Arrays.asList("context","finalized"))),"AUDIO_HEALTH_STATE");validateContext(WireJson.map(active.get("context")));if(Boolean.TRUE.equals(active.get("finalized")))validateStatus(WireJson.map(active.get("status")));}}
  }catch(IOException|RuntimeException e){if(opened!=null)try{opened.close();}catch(IOException ignored){}throw e;}
 }
 private static void require(boolean b,String code)throws IOException{if(!b)throw new IOException(code);}
 private static void check(File f,boolean dir)throws IOException{require(!Files.isSymbolicLink(f.toPath())&&f.getAbsoluteFile().equals(f.getCanonicalFile()),"AUDIO_HEALTH_PATH");if(f.exists())require(dir?f.isDirectory():f.isFile(),"AUDIO_HEALTH_PATH");}
 private void paths()throws IOException{check(directory,true);for(String s:new String[]{"",".partial",".lock"})check(new File(file.getPath()+s),false);}
 private static void sync(File f)throws IOException{try(FileChannel c=FileChannel.open(f.toPath(),StandardOpenOption.READ)){c.force(true);}}
 private static long number(Map<String,Object> v,String k)throws IOException{Object n=v.get(k);require((n instanceof Long||n instanceof Integer)&&((Number)n).longValue()>=0,"AUDIO_HEALTH_STATE");return ((Number)n).longValue();}
 private void save(Map<String,Object> candidate)throws IOException{paths();document.save(candidate);sync(directory);value=candidate;}
 private void validateContext(Map<String,Object> context)throws IOException{require(context.keySet().equals(new HashSet<>(Arrays.asList("account","peer","generation","clock_epoch")))&&account.equals(context.get("account"))&&context.get("peer") instanceof String&&((String)context.get("peer")).matches("[a-f0-9]{64}")&&context.get("clock_epoch") instanceof String&&((String)context.get("clock_epoch")).matches("[a-f0-9]{32}")&&number(context,"generation")>0,"AUDIO_HEALTH_STATE");}
 private static void validateStatus(Map<String,Object> status)throws IOException{require(status.keySet().equals(new HashSet<>(Arrays.asList("phase","queued_batches","queued_bytes","accepted_batches","saved_batches","last_saved_sequence","rejected_batches","unconfirmed_batches","error","health_error","recording_complete","source_link_verified")))&&Arrays.asList("STOPPED","FAILED").contains(status.get("phase"))&&Boolean.FALSE.equals(status.get("recording_complete"))&&Boolean.FALSE.equals(status.get("source_link_verified")),"AUDIO_HEALTH_STATE");for(String k:new String[]{"queued_batches","queued_bytes","accepted_batches","saved_batches","last_saved_sequence","rejected_batches","unconfirmed_batches"})number(status,k);for(String k:new String[]{"error","health_error"})require(status.get(k) instanceof String&&((String)status.get(k)).matches("[A-Z_]{0,90}"),"AUDIO_HEALTH_STATE");require(number(status,"queued_batches")==0&&number(status,"queued_bytes")==0&&number(status,"saved_batches")<=number(status,"accepted_batches")&&number(status,"unconfirmed_batches")==number(status,"accepted_batches")-number(status,"saved_batches"),"AUDIO_HEALTH_STATE");}
 public void start(Map<String,Object> context)throws IOException{require(!started&&!finished&&context!=null&&context.keySet().equals(new HashSet<>(Arrays.asList("account","peer","generation","clock_epoch")))&&account.equals(context.get("account"))&&context.get("peer") instanceof String&&((String)context.get("peer")).matches("[a-f0-9]{64}")&&context.get("clock_epoch") instanceof String&&((String)context.get("clock_epoch")).matches("[a-f0-9]{32}")&&number(context,"generation")>0,"AUDIO_HEALTH_CONTEXT");Map<String,Object> next=WireJson.map(WireJson.copy(value));Object previous=next.get("active");if(previous!=null&&!Boolean.TRUE.equals(WireJson.map(previous).get("finalized")))next.put("interrupted_runs",Math.addExact(number(next,"interrupted_runs"),1));next.put("active",WireJson.object("context",WireJson.copy(context),"finalized",false));save(next);started=true;}
 public void finish(Map<String,Object> status)throws IOException{require(started&&!finished&&value.get("active")!=null&&Arrays.asList("STOPPED","FAILED").contains(status.get("phase")),"AUDIO_HEALTH_STATE");Map<String,Object> next=WireJson.map(WireJson.copy(value));next.put("rejected_batches",Math.addExact(number(next,"rejected_batches"),number(status,"rejected_batches")));next.put("unconfirmed_batches",Math.addExact(number(next,"unconfirmed_batches"),number(status,"unconfirmed_batches")));String error=(String)status.get("error");require(error!=null&&error.matches("[A-Z_]{0,90}"),"AUDIO_HEALTH_STATE");if(!error.isEmpty())next.put("last_error",error);Map<String,Object> active=WireJson.map(next.get("active"));active.put("finalized",true);Map<String,Object> result=WireJson.map(WireJson.copy(status));result.remove("health_saved");validateStatus(result);active.put("status",result);save(next);finished=true;}
 public Map<String,Object> snapshot(){return WireJson.map(WireJson.copy(value));}
 public void close()throws IOException{document.close();}
}
